+import org.junit.jupiter.api.Assertions;
+import org.junit.jupiter.api.Test;
+
+/*
+ * @test
+ * @bug 8392557
+ * @modules jdk.incubator.code
+ * @library ../lib/
+ * @library ../
+ * @enablePreview
+ * @run junit TestIntersectionTargetLambda
+ */
+public class TestIntersectionTargetLambda {
+
+    interface Marker {}
+
+    @Reflect
+    public static String functionFirst() {
+        var f = (Function<String, String> & Marker) x -> x;
+        return f.apply("functionFirst");
+    }
+
+    @Test
+    public void testFunctionFirst() throws Throwable {
+        Method accessMethod = TestIntersectionTargetLambda.class.getDeclaredMethod("functionFirst");
+        CoreOp.FuncOp model = Op.ofMethod(accessMethod).orElseThrow();
+        MethodHandle handle = BytecodeGenerator.generate(MethodHandles.lookup(), model);
+        Assertions.assertEquals(functionFirst(), (String) handle.invokeExact());
+    }
+
+    @Reflect
+    public static String markerFirst() {
+        var f = (Marker & Function<String, String>) x -> x;
+        return f.apply("markerFirst");
+    }
+
+    @Test
+    public void testMarkerFirst() throws Throwable {
+        Method accessMethod = TestIntersectionTargetLambda.class.getDeclaredMethod("markerFirst");
+        CoreOp.FuncOp model = Op.ofMethod(accessMethod).orElseThrow();
+        MethodHandle handle = BytecodeGenerator.generate(MethodHandles.lookup(), model);
+        Assertions.assertEquals(markerFirst(), (String) handle.invokeExact());
+    }
+
+    interface Base {
+        String a();
+        String b();
+        String c();
+    }
+
+    interface A extends Base {
+        default String a() { return "A"; }
+    }
+
+    interface B extends Base {
+        default String b() { return "B"; }
+    }
+
+    @Reflect
+    public static String complex() {
+        var f = (A & B) () -> { return "C"; };
+        return f.c();
+    }
+
+    @Test
+    public void testComplex() throws Throwable {
+        Method accessMethod = TestIntersectionTargetLambda.class.getDeclaredMethod("complex");
+        CoreOp.FuncOp model = Op.ofMethod(accessMethod).orElseThrow();
+        MethodHandle handle = BytecodeGenerator.generate(MethodHandles.lookup(), model);
+        Assertions.assertEquals(complex(), (String) handle.invokeExact());
+    }
+
+    interface X {
+        String get();
+    }
+
+    interface Y {
+        String get();
+    }
+
+    interface Z extends X, Y {}
+
+    @Reflect
+    public static String overrideEquivalent() {
+        Z f = () -> "overrideEquivalent";
+        return f.get();
+    }
+
+    @Test
+    public void testOverrideEquivalent() throws Throwable {
+        Method accessMethod = TestIntersectionTargetLambda.class.getDeclaredMethod("overrideEquivalent");
+        CoreOp.FuncOp model = Op.ofMethod(accessMethod).orElseThrow();
+        MethodHandle handle = BytecodeGenerator.generate(MethodHandles.lookup(), model);
+        Assertions.assertEquals(overrideEquivalent(), (String) handle.invokeExact());
+    }
+}

